import {imageCanvas} from './photo.mjs';
import {createHostSession,createPhoneSession,parseScannerInvite,scannerQR,cleanScan} from './scanner-link.mjs';
export function installScannerLink({modal,scanner,identify,toast,armFeedback,beep,icon,savePhoto=()=>false,reviewPhoto=()=>{}}){
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let host=null,phone=null,pending=null,hardware=false,role='',generation=0,message='Sin escáner vinculado',state='idle',error='',buffer='',lastKey=0;const inbox=[],photos=[];
let invite=parseScannerInvite(location.href);
const update=()=>{$('#linkStatus').textContent=message;$('#disconnectScanner').hidden=!host&&!phone&&!hardware&&state!=='loading';if($('#linkMessage'))$('#linkMessage').textContent=message+(error&&state==='closed'?' · '+error:'');if($('#phoneScanButton'))$('#phoneScanButton').disabled=!phone?.connected;if($('#phoneRetry'))$('#phoneRetry').hidden=!!phone?.connected;updateInbox()};
const status=(event,g)=>{if(g!==generation)return;state=event.state;message=event.message;if(state==='error'){error=message;toast(message)}update()};
function updateInbox(){const node=$('#scannerInbox');node.hidden=!inbox.length&&!photos.length;if(node.hidden)return;node.innerHTML=(inbox.length?'<div><span>Lectura pendiente: <b>'+esc(inbox[0])+'</b> ('+inbox.length+')</span><button type="button" id="useIncoming">Usar código</button></div>':'')+(photos.length?'<div><span>Foto recibida para <b>'+esc(photos[0].code)+'</b></span><button type="button" id="reviewIncomingPhoto">Revisar foto del catálogo</button></div>':'');if($('#useIncoming'))$('#useIncoming').onclick=()=>{if($('#modal').open){toast('Cierra la ficha actual para usar la lectura pendiente.');return}identify(inbox.shift());updateInbox()};if($('#reviewIncomingPhoto'))$('#reviewIncomingPhoto').onclick=()=>{if($('#modal').open){toast('Cierra la ficha actual para revisar la foto pendiente.');return}reviewPhoto(photos.shift());updateInbox()}}
function receivePhoto(photo){const saved=savePhoto(photo),form=$('#product');if($('#modal').open&&form&&form.elements.namedItem('code').value.trim().toLowerCase()===photo.code.toLowerCase()){form.dispatchEvent(new CustomEvent('remote-catalog-photo',{detail:photo}));toast(saved?'Foto guardada en el inventario':'Foto incorporada. Completa y guarda el producto.');return}if(saved){toast('Foto guardada como portada del producto');return}if(!$('#modal').open||$('#newCode')){reviewPhoto(photo);toast('Foto incorporada. Completa y guarda el producto.');return}if(photos.length>=4)throw Error('Revisa las fotos pendientes primero.');photos.push(photo);updateInbox();toast('Foto recibida. Cierra la ficha actual y pulsa Revisar foto del catálogo.')}
function receive(code){code=cleanScan(code);if(!code)throw Error('Código inválido');const form=$('#product');if($('#modal').open&&form){form.elements.namedItem('code').value=code;if($('#productCodeStatus'))$('#productCodeStatus').textContent='Código recibido del teléfono. Revisa los datos y confirma el producto.';beep();toast('Código recibido en la ficha');return}if(!$('#modal').open){beep();identify(code);return}if(inbox.length>=10)throw Error('Completa las lecturas pendientes.');inbox.push(code);beep();toast('Lectura recibida. Quedó pendiente para no cerrar tu ficha.');updateInbox()}
function disconnect(){generation++;host?.close();phone?.close();host=phone=pending=null;hardware=false;role='';state='closed';message='Escáner desconectado';error='';if(invite){history.replaceState(null,'',location.pathname+location.search);invite=null}update()}
$('#disconnectScanner').onclick=()=>{disconnect();modal('<h2>Escáner desconectado</h2><p>Ya no se recibirán códigos de ese teléfono o lector. Puedes vincular otro cuando lo necesites.</p>')};
$('#modal').addEventListener('close',updateInbox);
function pendingPanel(){const node=$('#linkPending');if(!node)return;node.replaceChildren();if(!pending)return;node.innerHTML='<div class="panel"><h3>Autorizar teléfono</h3><p id="pendingName"></p><button type="button" id="approvePhone" class="primary">Autorizar este teléfono</button><button type="button" id="rejectPhone">Rechazar</button></div>';$('#pendingName').textContent=pending.name+' solicita enviar códigos a esta pantalla.';$('#approvePhone').onclick=()=>{armFeedback();pending?.approve();pending=null;pendingPanel();if($('#pairURL'))$('#modal').close()};$('#rejectPhone').onclick=()=>{pending?.reject();pending=null;pendingPanel()}}
async function showHost(){
modal('<h2>Vincular mi teléfono</h2><p>Desde el teléfono, abre este QR con su cámara normal o abre el enlace. Después autorízalo aquí.</p><p id="linkMessage" role="status"></p><div id="pairQR" class="pair-qr"></div><label>Enlace del escáner<input id="pairURL" readonly aria-label="Enlace para abrir en el teléfono"></label><button type="button" id="copyPairURL">Copiar enlace</button><div id="linkPending"></div><p>El enlace de invitación vence a los 10 minutos. Mantén abiertas ambas páginas. Se envían códigos y fotos de catálogo, sin sincronizar existencias.</p>');update();pendingPanel();
if(!host)return;const url=host.url;$('#pairURL').value=url;$('#copyPairURL').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Enlace copiado')}catch{$('#pairURL').focus();$('#pairURL').select();toast('Selecciona y copia el enlace mostrado')}};const node=$('#pairQR');node.textContent='Preparando QR…';try{const qr=await scannerQR(url);if(node.isConnected)node.innerHTML=qr}catch{if(node.isConnected)node.textContent='No se pudo generar el QR. Usa el enlace para abrirlo en tu teléfono.'}
}
async function startHost(){
if(host){showHost();return}disconnect();role='host';const g=++generation;state='loading';message='Preparando enlace para el teléfono…';modal('<h2>Preparando vinculación</h2><p id="linkMessage" role="status"></p><p>Requiere internet. El enlace usa el servicio público PeerJS para conectar ambas pantallas. No comparte tu catálogo.</p>');update();
try{const session=await createHostSession({baseURL:location.href,onStatus:event=>status(event,g),onScan:receive,onPhoto:receivePhoto,onPending:value=>{if(g!==generation){value.reject();return}pending=value;pendingPanel();toast('Autoriza el teléfono desde Vincular escáner')}});if(g!==generation){session.close();return}host=session;showHost();update()}catch(e){if(g===generation){state='error';error=message=e.message;update();toast(message)}}
}
function phonePanel(){modal('<h2>Teléfono como escáner</h2><p id="linkMessage" role="status"></p><button type="button" id="phoneScanButton" class="primary">'+icon('scan')+' Escanear y enviar</button><button type="button" id="phoneRetry">Reintentar vinculación</button><p>Los códigos se usarán en la pantalla receptora. Entradas, salidas y cantidades se confirman allí. Mantén esta página abierta y el teléfono activo.</p><p>La conexión puede fallar en redes restringidas. Prueba ambos equipos en la misma Wi-Fi.</p>');$('#phoneScanButton').onclick=scanToHost;$('#phoneRetry').onclick=showPhoneInvite;update()}
async function scanToHost(){if(!phone?.connected){toast('Primero vincula este teléfono.');return}scanner({onBack:phonePanel,onCode:async code=>{
const session=phone;
modal('<h2>Código y foto del producto</h2><p id="sendResult" role="status">Esperando confirmación de la pantalla receptora…</p><label class="code-photo-label">'+icon('camera')+' Tomar foto para el catálogo<input type="file" id="phoneCatalogPhoto" accept="image/*" capture="environment" disabled></label><div id="phonePhotoPreview" class="catalog-preview"></div><button type="button" id="scanAnother" disabled>Escanear otro código</button><button type="button" id="backPhone">Volver al enlace</button>');
const result=$('#sendResult'),next=$('#scanAnother'),photoInput=$('#phoneCatalogPhoto'),preview=$('#phonePhotoPreview');$('#backPhone').onclick=phonePanel;
photoInput.onchange=async e=>{const file=e.target.files[0];if(!file)return;photoInput.disabled=true;next.disabled=true;result.textContent='Preparando y enviando foto del producto…';
try{const canvas=await imageCanvas(file,800);const image=canvas.toDataURL('image/jpeg',.75);if(preview.isConnected)preview.innerHTML='<img alt="Foto enviada para el catálogo" src="'+image+'">';await session.sendPhoto(code,image);if(result.isConnected)result.textContent='Foto recibida para '+code+'. Si el producto ya existe, la portada quedó guardada; si es nuevo, completa y guarda su ficha en la pantalla receptora.'}
catch(err){if(result.isConnected)result.textContent=err.message}finally{if(photoInput.isConnected)photoInput.disabled=!phone?.connected;if(next.isConnected)next.disabled=!phone?.connected;e.target.value=''}
};
try{await session.send(code);if(result.isConnected){result.textContent='Código recibido: '+code+'. Ahora puedes tomar su foto para el catálogo.';photoInput.disabled=false}}
catch(e){if(result.isConnected)result.textContent=e.message}
finally{if(next.isConnected){next.disabled=!phone?.connected;next.onclick=scanToHost}}
}})}
async function connectPhone(){
if(phone?.connected){phonePanel();return}if(!invite){toast('Abre primero el QR o enlace generado en la pantalla receptora.');return}const name=$('#phoneName')?.value||'Teléfono';const keep=invite;disconnect();invite=keep;role='phone';const g=++generation;state='loading';message='Conectando teléfono…';phonePanel();
try{const session=await createPhoneSession(keep,{name,onStatus:event=>status(event,g)});if(g!==generation){session.close();return}phone=session;update()}catch(e){if(g===generation){state='error';error=message=e.message;update();toast(message)}}
}
function showPhoneInvite(){modal('<h2>Usar este teléfono como escáner</h2><p>Conecta con la tablet o computadora que generó el enlace y autoriza este teléfono en esa pantalla.</p><label>Nombre para reconocer este teléfono<input id="phoneName" value="Mi teléfono" maxlength="50"></label><button type="button" id="connectPhone" class="primary">Vincular con la pantalla receptora</button><p>Necesita internet y un enlace PeerJS. Se envían códigos y las fotos que tomes; tu inventario no se copia ni sincroniza.</p>');$('#connectPhone').onclick=connectPhone}
function hardwarePanel(){
modal('<h2>Escáner Bluetooth o USB</h2><ol><li>En los ajustes Bluetooth de la tablet, empareja el lector. Si es USB, conéctalo.</li><li>Configura el lector en modo teclado / HID, con Enter al final.</li><li>Activa la entrada y prueba un código.</li></ol><p>La web recibe lo que el lector escribe; no puede emparejar Bluetooth directamente. Lectores que requieren una aplicación propia pueden no ser compatibles.</p><button type="button" id="activateHardware" class="primary">Activar entrada del lector</button><form id="hardwareForm"><label>Código de prueba<input name="code" id="hardwareCode" autocomplete="off" placeholder="Toca aquí y escanea"></label><button>Usar código leído</button></form>');
$('#activateHardware').onclick=()=>{armFeedback();hardware=true;message='Entrada de lector activada · modo teclado';state='hardware';update();$('#hardwareCode').focus()};$('#hardwareForm').onsubmit=e=>{e.preventDefault();const code=cleanScan(e.target.elements.namedItem('code').value);if(!code){toast('Escanea primero un código.');return}armFeedback();beep();identify(code)};
}
function linkAsScanner(){
armFeedback();if(phone?.connected){phonePanel();return}if(host){toast('Esta pantalla está recibiendo un escáner. Desvincúlalo primero para usarla como teléfono escáner.');return}
scanner({qrOnly:true,onBack:()=>$('#linkScanner').click(),onCode:value=>{
const parsed=parseScannerInvite(value);let sameSite=false;try{sameSite=new URL(value).origin===new URL(location.href).origin}catch{}
if(!parsed||!sameSite){modal('<h2>Este QR no es de vinculación</h2><p>Escanea el QR generado por Vincular escáner en la tablet o computadora de Mi Torno Gestión.</p><button id="retryLinkQR" type="button" class="primary">Volver a leer QR</button>');$('#retryLinkQR').onclick=linkAsScanner;return}
invite=parsed;connectPhone();
}});
}
$('#linkAsScanner').onclick=linkAsScanner;
$('#linkScanner').onclick=()=>{
armFeedback();if(role==='phone'&&phone){phonePanel();return}if(host){showHost();return}if(invite){showPhoneInvite();return}
modal('<h2>Vincular escáner</h2><p>Elige cómo recibir los códigos en esta pantalla.</p><button type="button" id="chooseHardware" class="primary">'+icon('scan')+' Lector Bluetooth / USB</button><button type="button" id="choosePhone">'+icon('camera')+' Usar mi teléfono como escáner</button><p>El lector físico funciona como teclado. El teléfono se conecta mediante QR o enlace, con autorización en esta pantalla.</p>');$('#chooseHardware').onclick=hardwarePanel;$('#choosePhone').onclick=startHost;
};
document.addEventListener('keydown',e=>{if(!hardware||e.ctrlKey||e.altKey||e.metaKey)return;const target=e.target;if(target?.closest?.('input,textarea,select,[contenteditable="true"]'))return;const now=Date.now();if(now-lastKey>120)buffer='';lastKey=now;if(e.key==='Enter'){const code=cleanScan(buffer);buffer='';if(code&&code.length>=3){e.preventDefault();receive(code)}}else if(e.key.length===1){buffer=(buffer+e.key).slice(-160)}});
window.addEventListener('pagehide',disconnect);if(invite)showPhoneInvite();update();return {disconnect};
}
